package com.example

/**
 * Curated, 100% syllabus-aligned Flashcards for Agriculture & Food Technology (කෘෂි හා ආහාර තාක්ෂණය).
 * Part 1: Categories 1 to 10 (20 distinct questions per category = 200 unique questions).
 */
object FlashcardBankAgriSetsPart1 {

  fun getAgriSet(s: Int, c: Int): CardContentTuple? {
    return when (s) {
      1 -> getSet1(c)
      2 -> getSet2(c)
      3 -> getSet3(c)
      4 -> getSet4(c)
      5 -> getSet5(c)
      6 -> getSet6(c)
      7 -> getSet7(c)
      8 -> getSet8(c)
      9 -> getSet9(c)
      10 -> getSet10(c)
      else -> null
    }
  }

  // Set 1: පාංශු විද්‍යාව සහ භෞතික ගුණ (Soil Science & Physical Properties)
  private fun getSet1(c: Int): CardContentTuple = when (c) {
    1 -> CardContentTuple("කෘෂිකාර්මික පසක (Agricultural Soil) ප්‍රධාන සංඝටක 4 සහ ඒවායේ සාමාන්‍ය ප්‍රතිශත මොනවාද?", "ඛනිජ ද්‍රව්‍ය (45%), කාබනික ද්‍රව්‍ය (5%), පාංශු ජලය (25%), සහ පාංශු වාතය (25%).", "විභාග උපදෙස: පසෙහි පරිමා ප්‍රතිශත සංයුතියයි.", "කෘෂිකර්මය • කාණ්ඩය 1")
    2 -> CardContentTuple("පාංශු වයනය (Soil Texture) යනු කුමක්ද?", "පසෙහි අඩංගු වැලි (Sand), රොන්මඩ (Silt), සහ මැටි (Clay) යන අංශුවල සාපේක්ෂ ප්‍රතිශත අනුපාතයයි.", "විභාග උපදෙස: වයනය මිනිසාට පහසුවෙන් වෙනස් කළ නොහැක.", "කෘෂිකර්මය • කාණ්ඩය 1")
    3 -> CardContentTuple("පාංශු ව්‍යුහය (Soil Structure) යනු කුමක්ද?", "තනි පාංශු අංශු එකිනෙක බැඳී පාංශු කැට හෙවත් සමූහක (Aggregates / Peds) ලෙස සකස් වී ඇති ආකාරයයි.", "විභාග උපදෙස: සී සෑම හා කාබනික පොහොර යෙදීමෙන් ව්‍යුහය වෙනස් කළ හැක.", "කෘෂිකර්මය • කාණ්ඩය 1")
    4 -> CardContentTuple("බෝග වගාවට වඩාත්ම සුදුසු පාංශු වයනය කුමක්ද?", "මාවැලි පස හෙවත් ලෝම් පස (Loam soil) - වැලි, රොන්මඩ සහ මැටි සමබරව අඩංගු පසයි.", "විභාග උපදෙස: ජල රඳවා ගැනීම සහ ජල වහනය දෙකම යහපත්ය.", "කෘෂිකර්මය • කාණ්ඩය 1")
    5 -> CardContentTuple("මැටි පසක (Clay Soil) පවතින ප්‍රධාන ලක්ෂණ 2ක් දක්වන්න.", "අතිශය කුඩා ක්ෂුද්‍ර සිදුරු බහුල වීම, අධික ජල රඳවා ගැනීමේ හැකියාව, සහ වාතනය හා ජල වහනය දුර්වල වීම.", "විභාග උපදෙස: තෙත් වූ විට ඇලෙන සුළු වන අතර වියළි විට ඉරිතලා යයි.", "කෘෂිකර්මය • කාණ්ඩය 1")
    6 -> CardContentTuple("වැලි පසක (Sandy Soil) ප්‍රධාන දුර්වලතාවය කුමක්ද?", "විශාල මහා සිදුරු ඇති බැවින් ජලය සහ පෝෂක රඳවා ගැනීමේ හැකියාව ඉතා අඩු වීම (ශීඝ්‍රයෙන් පෝෂක කාන්දු වේ).", "විභාග උපදෙස: කාබනික ද්‍රව්‍ය එකතු කිරීමෙන් ගුණාත්මක බව වැඩි කළ හැක.", "කෘෂිකර්මය • කාණ්ඩය 1")
    7 -> CardContentTuple("පාංශු පැතිකඩක (Soil Profile) ප්‍රධාන ක්ෂිතිජ (Horizons) අනුපිළිවෙල දක්වන්න.", "O ක්ෂිතිජය (කාබනික ස්ථරය) -> A ක්ෂිතිජය (මතුපිට පස) -> B ක්ෂිතිජය (යටි පස) -> C ක්ෂිතිජය (ප්‍රධාන පාෂාණ කොටස්) -> R (මව් පාෂාණය).", "විභාග උපදෙස: බෝග මුල් බහුලව පැතිරෙන්නේ A ක්ෂිතිජයේය.", "කෘෂිකර්මය • කාණ්ඩය 1")
    8 -> CardContentTuple("මතුපිට පස (Topsoil) සහ යටි පස (Subsoil) අතර වෙනස කුමක්ද?", "මතුපිට පස කාබනික ද්‍රව්‍ය සහ ක්ෂුද්‍රජීවීන් බහුල අඳුරු පැහැති සාරවත් පසකි; යටි පස කාබනික ද්‍රව්‍ය අඩු, ඛනිජ බහුල, තද පැහැයෙන් අඩු ස්ථරයකි.", "විභාග උපදෙස: පාංශු ඛාදනයේදී මුලින්ම විනාශ වන්නේ මතුපිට පසයි.", "කෘෂිකර්මය • කාණ්ඩය 1")
    9 -> CardContentTuple("පසෙහි ක්ෂේත්‍ර ධාරිතාව (Field Capacity) යනු කුමක්ද?", "වර්ෂාවකින් හෝ ජල සම්පාදනයකින් පසු ගුරුත්වාකර්ෂණ ජලය සම්පූර්ණයෙන්ම බැස ගිය පසු පසෙහි රඳා පවතින උපරිම ජල ප්‍රමාණයයි.", "විභාග උපදෙස: ශාක මුල්වලට ජලය ලබා ගැනීමට වඩාත් සුදුසු තත්ත්වයයි.", "කෘෂිකර්මය • කාණ්ඩය 1")
    10 -> CardContentTuple("ස්ථිර මැලවීමේ ලක්ෂ්‍යය (Permanent Wilting Point - PWP) යනු කුමක්ද?", "පසෙහි තෙතමනය කෙතරම් අඩු වී ඇත්ද යත්, ශාකයට තවදුරටත් ජලය උරාගත නොහැකිව මැලවී යන අතර, නැවත ජලය දැමුවද පණ ගැන්විය නොහැකි අවස්ථාවයි.", "විභාග උපදෙස: ක්ෂේත්‍ර ධාරිතාව සහ PWP අතර පරාසය 'ලභ්‍ය ජලය' (Available Water) වේ.", "කෘෂිකර්මය • කාණ්ඩය 1")
    11 -> CardContentTuple("කේෂාකර්ෂණ ජලය (Capillary Water) බෝග සඳහා වැදගත් වන්නේ ඇයි?", "පසෙහි ක්ෂුද්‍ර සිදුරු තුළ මතුපිට ආතතිය මඟින් රඳවාගෙන ඇති, ශාක මුල්වලට සෘජුවම උරාගත හැකි ප්‍රධානතම ජල ආකාරය මෙය වන බැවිනි.", "විභාග උපදෙස: ගුරුත්වාකර්ෂණ ජලය පහළට ගලා යයි.", "කෘෂිකර්මය • කාණ්ඩය 1")
    12 -> CardContentTuple("පසෙහි වාතනය (Soil Aeration) දුර්වල වූ විට මුල්වලට සිදුවන හානිය කුමක්ද?", "ඔක්සිජන් නොමැතිකම නිසා මුල්වල සෛලීය ශ්වසනය අඩපණ වී, මුල් කුණුවීම සහ පෝෂක උරාගැනීම ඇණහිට ශාකය මිය යාම.", "විභāග උපදෙස: ජලයෙන් යටවූ බිම්වල වාතනය බිඳ වැටේ.", "කෘෂිකර්මය • කාණ්ඩය 1")
